private static Comparable getValueForComparison(Metric metric, String value) throws NotImplementedException {
  try {
    if (isADouble(metric)) {
      return Double.parseDouble(value);
    }
    if (isAInteger(metric)) {
      return parseInteger(value);
    }
    if (isAString(metric)) {
      return value;
    }
    if (isABoolean(metric)) {
      return Integer.parseInt(value);
    }
    if (isAWorkDuration(metric)) {
      return Long.parseLong(value);
    }
  } catch (NumberFormatException | NullPointerException e) {
    // Handle the parsing error, e.g., log the error or return a default value
  }
  throw new NotImplementedException(metric.getType().toString());
}
